import {forwardSignal,MODEL_VERSION} from './forward-core.js';
import {checkForwardRows} from './forward-monitor.js';
export function installForward({native,request}){
 let panel=null,rows=[],error='',checking=false,visible=100;
 const en=()=>document.documentElement.lang==='en',tr=(a,b)=>en()?b:a,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const date=t=>Number.isFinite(t)&&t>0?new Date(t).toLocaleString(en()?'en-US':'tr-TR',{hour12:false}):'—';
 const price=n=>Number.isFinite(n)?'$'+Number(n).toLocaleString(en()?'en-US':'tr-TR',{maximumFractionDigits:8}):'—';
 const duration=r=>{if(!r.targetAt||!r.signalAt)return '—';const h=Math.max(0,(r.targetAt-r.signalAt)/3600000),d=Math.floor(h/24),hours=Math.floor(h%24),mins=Math.round(h%1*60);return (d?d+tr(' gün ',' d '):'')+hours+tr(' saat ',' h ')+mins+tr(' dk',' min');};
 async function refresh(){try{const r=await native().history(),all=JSON.parse(r.rows||'[]');rows=all.filter(r=>(r.strategyVersion===MODEL_VERSION||r.priorCompleted===true)&&r.status!=='REJECTED');}catch(e){error=tr('Kayıtlar okunamadı: ','Could not read records: ')+e.message;}if(panel&&!panel.hidden)draw();}
 async function check(){if(checking)return;checking=true;try{const r=await native().history(),errors=await checkForwardRows(JSON.parse(r.rows||'[]'),request,row=>native().mark({row}));error=errors.length?tr('Bazı fiyatlar güncellenemedi.','Some prices could not be updated.'):'';await refresh();}catch(e){error=tr('Fiyatlar güncellenemedi.','Prices could not be updated.');}finally{checking=false;if(panel&&!panel.hidden)draw();}}
 window.forwardObserve=async s=>{const r=forwardSignal(s);if(r){await native().observe({row:JSON.stringify(r)});await refresh();}};
 const style=document.createElement('style');style.textContent=`#tf-panel{position:fixed;inset:0 0 64px;z-index:910;background:#111113;color:#f5eeee;overflow:auto;font:14px system-ui}#tf-panel[hidden]{display:none}#tf-panel *{box-sizing:border-box}#tf-panel header{position:sticky;top:0;padding:18px;background:#241e21;z-index:2;display:flex;justify-content:space-between;align-items:center}#tf-panel h2{font-size:20px;margin:0}#tf-panel main{max-width:850px;margin:auto;padding:18px}#tf-panel .card{padding:20px;border:1px solid #4b3b41;border-radius:18px;background:#241e21;margin-bottom:14px}#tf-panel button{background:#852b3e;border:1px solid #b44d64;border-radius:10px;color:white;padding:10px 14px}#tf-panel .muted{color:#b9aeb2;font-size:12px;line-height:1.6}#tf-panel .grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;overflow-wrap:anywhere}#tf-panel .metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:18px}#tf-panel .metric{padding:12px 6px;text-align:center;border-radius:12px;background:#39232c}#tf-panel .number{display:block;font-size:24px;font-weight:700;color:#efa0b2}#tf-panel .tp{color:#efa0b2}#tf-panel .big{font-size:30px;font-weight:700;color:#efa0b2;margin:8px 0}#tf-panel .rowhead{display:flex;justify-content:space-between;gap:12px;margin-bottom:18px}#tf-panel .rowhead h3{margin:0 0 5px;font-size:19px}#tf-panel .badge{align-self:flex-start;white-space:nowrap;border-radius:8px;padding:6px 9px;background:#39232c;color:#efa0b2;font-weight:700;font-size:12px}#tf-panel .warn{color:#f5c48f}body[data-forward-open] #bt-launch{display:none}body[data-forward-open] #tl-nav button{color:#a8949c!important}body[data-forward-open] #tl-forward-tab{color:#efa0b2!important}`;document.head.append(style);
 function size(){if(panel)panel.style.bottom=(document.querySelector('#tl-nav')?.getBoundingClientRect().height||64)+'px';}
 function close(){if(panel)panel.hidden=true;document.body.removeAttribute('data-forward-open');}
 function draw(){const tp=rows.filter(r=>r.status==='TP').length,open=rows.filter(r=>r.status==='OPEN').length,timed=rows.filter(r=>r.status==='TIMEOUT').length,list=rows.slice().sort((a,b)=>b.signalAt-a.signalAt),field=(name,value)=>`<div><span class="muted">${name}</span><br><strong>${value}</strong></div>`;
 panel.innerHTML=`<header><h2>${tr('İleri Test','Forward Test')}</h2><button id="tf-close">${tr('Geri','Back')}</button></header><main><section class="card"><div class="muted">LONG / SHORT · 4H</div><div class="big">${tp} / ${rows.length} TP</div><div class="muted">${tr('Hedefe ulaşma oranı','Target hit rate')}: ${rows.length?(100*tp/rows.length).toFixed(1)+'%':'—'}</div><div class="metrics"><div class="metric"><b class="number">${tp}</b>${tr('Başarılı','Successful')}</div><div class="metric"><b class="number">${open}</b>${tr('Açık','Open')}</div><div class="metric"><b class="number">${timed}</b>${tr('7 gün sonu','7-day exit')}</div></div>${error?`<p class="warn">${esc(error)}</p>`:''}</section>${list.slice(0,visible).map(r=>{const done=r.status==='TP',status=done?tr('Başarılı · TP','Successful · TP'):r.status==='TIMEOUT'?tr('7 gün sonu','7-day exit'):tr('Açık','Open');return `<article class="card"><div class="rowhead"><div><h3>${esc(r.symbol)}</h3><span class="muted">${esc(r.side||'LONG')} · 4H · ${esc(r.exchange||'').toUpperCase()}</span></div><span class="badge">${status}</span></div><div class="grid">${field(tr('Sinyal tarihi','Signal time'),date(r.signalAt))}${field(done?tr('TP tarihi','TP time'):tr('Son çıkış zamanı','Exit deadline'),date(done?r.targetAt:r.deadline))}${field(tr('Giriş referansı','Reference entry'),price(r.entry))}${field(tr('TP fiyatı','TP price'),price(r.tp))}${field(done?tr('Hedef getirisi','Target return'):tr('Son fiyat','Last price'),done?'+5.00%':price(r.lastPrice))}${field(done?tr('TP süresi','Time to TP'):tr('Son kontrol','Last checked'),done?duration(r):date(r.lastCheckedAt))}${done?field(tr('Kaydedildiği zaman','Registered at'),date(r.registeredAt))+field(tr('Son kaydedilen fiyat','Last recorded price'),price(r.lastPrice)):''}</div>${!done&&r.status==='TIMEOUT'?`<p>${tr('Çıkış','Exit')}: ${price(r.exitPrice)} · ${Number.isFinite(r.returnPct)?r.returnPct.toFixed(2)+'%':'—'}</p>`:''}${!done&&r.coverageGap?`<p class="warn">${tr('Fiyat geçmişinde eksik veri var.','Price history has missing data.')}</p>`:''}</article>`;}).join('')||`<section class="card">${tr('Henüz işlem yok.','No trades yet.')}</section>`}${list.length>visible?`<button id="tf-more">${tr('Daha fazla','Show more')}</button>`:''}</main>`;
 panel.querySelector('#tf-close').onclick=close;const more=panel.querySelector('#tf-more');if(more)more.onclick=()=>{visible+=100;draw();};}
 window.openForwardTest=()=>{window.closeTradeJournal?.();if(!panel){panel=document.createElement('section');panel.id='tf-panel';document.body.append(panel);}panel.hidden=false;document.body.setAttribute('data-forward-open','true');size();draw();refresh();check();};window.closeForwardTest=close;
 window.addEventListener('resize',size);window.addEventListener('popstate',close);window.addEventListener('tradingly-scan-completed',refresh);document.addEventListener('visibilitychange',()=>{if(!document.hidden){refresh();check();}});new MutationObserver(()=>{if(panel&&!panel.hidden)draw();}).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});setInterval(()=>{if(panel&&!panel.hidden)refresh();},3000);setInterval(()=>{if(!document.hidden)check();},180000);refresh();check();
}
